const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // PG* env vars
const router = express.Router();

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString('base64url');

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString());
    if (typeof ts === 'string' && typeof id === 'string') return [ts, id];
  } catch {}
  return null;
}

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let after = null;
  if (req.query.cursor !== undefined) {
    after = decodeCursor(req.query.cursor);
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // Fetch one extra row to know whether another page exists.
    const { rows } = await pool.query(
      `SELECT id, created_at, created_at::text AS cursor_ts, customer_id, status, total
         FROM orders
        ${after ? 'WHERE (created_at, id) < ($2::timestamptz, $3::bigint)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...(after ?? [])]
    );

    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Well-formed cursor carrying an unparseable timestamp/id: client error, not a 500.
    if (after && err.code?.startsWith('22')) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
